<?php
require_once __DIR__.'/config.php'; require_once __DIR__.'/includes/functions.php'; $pageTitle='Timetable'; require_role(['admin','teacher','student']); require_once __DIR__.'/includes/header.php';$error='';$tid=null;$studentClassId=null;if(user()['role']==='student'){$q=$pdo->prepare('SELECT class_id FROM students WHERE user_id=? AND status=\'active\'');$q->execute([user()['id']]);$studentClassId=(int)$q->fetchColumn();}if(user()['role']==='teacher'){$q=$pdo->prepare('SELECT id FROM teachers WHERE user_id=?');$q->execute([user()['id']]);$tid=$q->fetchColumn();}
if($_SERVER['REQUEST_METHOD']==='POST' && in_array(user()['role'],['admin','teacher'],true)){verify_csrf();try{$classId=(int)$_POST['class_id'];$subjectId=(int)$_POST['subject_id'];$teacherId=(int)$_POST['teacher_id'];$termId=(int)$_POST['term_id'];$day=(int)$_POST['day_of_week'];$start=$_POST['start_time'];$end=$_POST['end_time'];if($start >= $end)throw new RuntimeException('End time must be after start time.');if(user()['role']==='teacher' && ($teacherId!== (int)$tid || !user_has_teacher_class($pdo,$tid,$classId) || !user_has_teacher_subject($pdo,$tid,$subjectId)))throw new RuntimeException('You may only schedule your assigned classes and subjects.');
 $st=$pdo->prepare("SELECT id FROM timetable_entries WHERE term_id=? AND class_id=? AND day_of_week=? AND start_time<? AND end_time>? LIMIT 1");$st->execute([$termId,$classId,$day,$end,$start]);if($st->fetch())throw new RuntimeException('That class already has an overlapping lesson.');
 $st=$pdo->prepare("SELECT id FROM timetable_entries WHERE term_id=? AND teacher_id=? AND day_of_week=? AND start_time<? AND end_time>? LIMIT 1");$st->execute([$termId,$teacherId,$day,$end,$start]);if($st->fetch())throw new RuntimeException('That teacher already has an overlapping lesson.');
 $st=$pdo->prepare('INSERT INTO timetable_entries(class_id,subject_id,teacher_id,term_id,day_of_week,start_time,end_time,room,created_by) VALUES(?,?,?,?,?,?,?,?,?)');$st->execute([$classId,$subjectId,$teacherId,$termId,$day,$start,$end,trim($_POST['room']??''),user()['id']]);audit($pdo,'create','timetable_entries',(int)$pdo->lastInsertId());flash('success','Timetable entry saved.');redirect('timetable.php');}catch(Throwable $e){$error=$e->getMessage();}}
$classes=$pdo->query("SELECT * FROM classes WHERE active=1 ORDER BY FIELD(name,'JSS1','JSS2','JSS3','SSS1','SSS2','SSS3'),section")->fetchAll();$subjects=$pdo->query("SELECT * FROM subjects WHERE active=1 ORDER BY subject_name")->fetchAll();$teachers=$pdo->query("SELECT t.id,u.full_name,t.staff_no FROM teachers t JOIN users u ON u.id=t.user_id WHERE u.status='active' ORDER BY u.full_name")->fetchAll();$terms=$pdo->query("SELECT * FROM academic_terms ORDER BY is_current DESC,id DESC")->fetchAll();$rows=[];$params=[];$sql="SELECT tt.*,c.name class_name,c.section,sub.subject_name,u.full_name teacher,t.session_name,t.term_name FROM timetable_entries tt JOIN classes c ON c.id=tt.class_id JOIN subjects sub ON sub.id=tt.subject_id JOIN teachers tr ON tr.id=tt.teacher_id JOIN users u ON u.id=tr.user_id JOIN academic_terms t ON t.id=tt.term_id WHERE 1=1";if(user()['role']==='teacher'){$sql.=' AND tt.teacher_id=?';$params[]=$tid;}elseif(user()['role']==='student'){$sql.=' AND tt.class_id=?';$params[]=$studentClassId;}$sql.=' ORDER BY tt.term_id DESC,tt.day_of_week,tt.start_time';$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();$success=flash('success');$days=[1=>'Monday',2=>'Tuesday',3=>'Wednesday',4=>'Thursday',5=>'Friday'];
?><h2>My Timetable</h2><?php if(user()['role']!=='student'): ?><?php if($success): ?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card p-4 mb-4"><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="col-md-3"><label>Class</label><select class="form-select" name="class_id" required><?php foreach($classes as $c): ?><?php if(user()['role']==='teacher' && !user_has_teacher_class($pdo,$tid,(int)$c['id'])) continue; ?><option value="<?=$c['id']?>"><?=e($c['name'].' '.$c['section'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label>Subject</label><select class="form-select" name="subject_id" required><?php foreach($subjects as $s): ?><?php if(user()['role']==='teacher' && !user_has_teacher_subject($pdo,$tid,(int)$s['id'])) continue; ?><option value="<?=$s['id']?>"><?=e($s['subject_name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label>Teacher</label><select class="form-select" name="teacher_id" required><?php foreach($teachers as $t): ?><?php if(user()['role']==='teacher' && (int)$t['id']!== (int)$tid) continue; ?><option value="<?=$t['id']?>"><?=e($t['full_name'].' — '.$t['staff_no'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label>Term</label><select class="form-select" name="term_id" required><?php foreach($terms as $t): ?><option value="<?=$t['id']?>"><?=e($t['session_name'].' — '.$t['term_name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label>Day</label><select class="form-select" name="day_of_week"><?php foreach($days as $n=>$d): ?><option value="<?=$n?>"><?=e($d)?></option><?php endforeach;?></select></div><div class="col-md-2"><label>Start</label><input class="form-control" type="time" name="start_time" required></div><div class="col-md-2"><label>End</label><input class="form-control" type="time" name="end_time" required></div><div class="col-md-3"><label>Room</label><input class="form-control" name="room"></div><div class="col-md-3 d-flex align-items-end"><button class="btn btn-primary w-100">Add lesson</button></div></form></div><?php endif; ?><div class="card p-3 table-responsive"><table class="table"><thead><tr><th>Day</th><th>Time</th><th>Class</th><th>Subject</th><th>Teacher</th><th>Term</th><th>Room</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($days[$r['day_of_week']]??'')?></td><td><?=e(substr($r['start_time'],0,5).' - '.substr($r['end_time'],0,5))?></td><td><?=e($r['class_name'].' '.$r['section'])?></td><td><?=e($r['subject_name'])?></td><td><?=e($r['teacher'])?></td><td><?=e($r['session_name'].' '.$r['term_name'])?></td><td><?=e($r['room'])?></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/includes/footer.php';
